#pragma once
/**
 * @file ReadmitRunEnd.hpp
 * @brief Run-end report of the re-admission continuity (E2 seed-first re-admission and the block re-coupling edge).
 *
 * The run-end reports defined in ReadmitRunEnd.cpp; each is a row of kNetworkRunEndReports
 * (network/runend/RunEnd.hpp).
 */

namespace GnssProcessor {

// ---- Run-end reports (generated by scripts/nom_td_cut.py) ----

struct NetworkRunEndView;

/**
 * @brief Run-end report: re-admission continuity.
 *
 * Re-admission continuity: the seed-first re-admission (parked, seeded, moved, outlier)
 * and the block re-coupling edge.
 *
 * Gate: prints under `config_.networkReadmitSeedHorizonS() > 0.0 ||
 * config_.networkReadmitCouplingMargEp() > 0`.
 *
 * @param v The run at its end (network/runend/RunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkReadmitRunEnd(const NetworkRunEndView& v);

// ---- End of the run-end reports ----

} // namespace GnssProcessor
